import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;
public class PassStore{
 private final Path file;private final List<String>damaged=new ArrayList<>();public PassStore(Path file){this.file=file;}public List<String>damagedLines(){return List.copyOf(damaged);}
 public void add(BusPass p)throws IOException{Path parent=file.toAbsolutePath().getParent();if(parent!=null)Files.createDirectories(parent);try(BufferedWriter w=Files.newBufferedWriter(file,StandardCharsets.UTF_8,StandardOpenOption.CREATE,StandardOpenOption.APPEND)){w.write(p.toLine());w.newLine();w.flush();}}
 public BusPass find(String id)throws IOException{damaged.clear();if(!Files.exists(file))throw new NoSuchFileException(file.toString());int n=0;try(BufferedReader r=Files.newBufferedReader(file,StandardCharsets.UTF_8)){String line;while((line=r.readLine())!=null){n++;if(line.isBlank())continue;try{BusPass p=BusPass.parse(line);if(p.passId().equals(id))return p;}catch(BusPass.DamagedRecordException e){damaged.add("line "+n+": "+e.getMessage());}}}return null;}
 public List<BusPass>onRoute(String route)throws IOException{damaged.clear();List<BusPass>out=new ArrayList<>();if(!Files.exists(file))throw new NoSuchFileException(file.toString());int n=0;try(BufferedReader r=Files.newBufferedReader(file,StandardCharsets.UTF_8)){String line;while((line=r.readLine())!=null){n++;if(line.isBlank())continue;try{BusPass p=BusPass.parse(line);if(p.routeNo().equals(route))out.add(p);}catch(BusPass.DamagedRecordException e){damaged.add("line "+n+": "+e.getMessage());}}}return out;}
}
